# -*- coding: utf-8 -*-
import json,re,html
from pathlib import Path
root=Path(__file__).parent
copy=json.loads((root/'copy-approved.json').read_text())
introductions=json.loads((root/'card-introductions.json').read_text(encoding='utf-8'))
paths=['<path d="M16 28V10M16 23C5 23 4 13 6 9c8 1 10 7 10 14ZM17 27c11-2 13-10 12-15-8 0-12 7-12 15Z"/>','<circle cx="17" cy="17" r="13"/><path d="M17 8v10l7 4"/>','<path d="m17 5 13 7-13 7L4 12l13-7Zm-13 14 13 7 13-7M4 26l13 7 13-7"/>','<circle cx="17" cy="10" r="4"/><circle cx="6" cy="15" r="3"/><circle cx="28" cy="15" r="3"/><path d="M10 30v-5a7 7 0 0 1 14 0v5ZM2 28v-5a4 4 0 0 1 6-4M32 28v-5a4 4 0 0 0-6-4"/>']
for lang,text in copy.items():
 ru=lang=='ru';sections=text.split('\n---\n');pre=sections[0].split('### 1.')[0]
 intro=re.search(r'^Мы .+$' if ru else r'^We .+$',pre,re.M)[0]
 question=re.search(r'^# (.+)$',pre,re.M)[1];question=question.replace('должен','может') if ru else 'How Can AI Help You?';cards=[];templates=[]
 for i,s in enumerate(sections):
  title=re.search(r'^### \d\. (.+)$',s,re.M)[1].capitalize();body=s.split(re.search(r'^### \d\. (.+)$',s,re.M)[1],1)[1].strip();ps=body.split('\n\n');lead=ps[0].strip('*');cta=ps[-1].strip('*');paras=ps[1:-1]
  lead=introductions[lang].get(str(i),lead)
  if i==3: paras=['Мы можем сделать всё за вас и для вас — от идеи до результата. Вам останется только использовать готовое решение.' if ru else 'We can do everything for you — from idea to finished result. All you have to do is use the solution we create for you.']
  icon=f'<svg viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths[i]}</svg>'
  cards.append(f'<details class="card card-{i}"><summary><span class="icon">{icon}</span><span class="card-title">{html.escape(title)}</span><span class="plus" aria-hidden="true">+</span></summary><div class="card-body"><p class="lead">{html.escape(lead)}</p><p class="preview">{html.escape(paras[0])}</p><button class="read-more" data-service="{i}" aria-haspopup="dialog">'+('Читать больше' if ru else 'Read More')+' <span aria-hidden="true">→</span></button></div></details>')
  templates.append(f'<template id="service-{i}"><h2>{html.escape(title)}</h2><p class="lead">{html.escape(lead)}</p>'+''.join(f'<p>{html.escape(p)}</p>' for p in paras)+f'<button class="contact-button">{html.escape(cta)}</button></template>')
 brand='AIforPsy';about='О нас' if ru else 'About Us';services='Услуги' if ru else 'Services';contact='Контакты' if ru else 'Contact';start='Начать' if ru else 'Get Started'
 headline='Психология. Коучинг.<br>Консультирование.' if ru else 'Psychology. Coaching.<br>Consulting.'
 accent='Теперь — вместе с искусственным интеллектом.' if ru else 'Now — powered by AI.'
 find='Найти своё решение' if ru else 'Find Your Solution';quote='Технологии меняются.<br>Ценности остаются.' if ru else 'Technology changes.<br>Our values remain.'
 strap='Ваш опыт. Новые возможности.' if ru else 'Your experience. New possibilities.'
 features=['Глубокое понимание профессии','Современные решения','Больше людей. Больше возможностей'] if ru else ['Deep understanding of your profession','Modern solutions','More people. More possibilities']
 page=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{brand}</title><meta name="description" content="{html.escape(intro,quote=True)}"><link rel="stylesheet" href="/style.css?v=20261005-7"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="alternate" hreflang="ru" href="/ru/"><link rel="alternate" hreflang="en" href="/en/"></head><body><header class="header wrap"><a class="brand" href="/{lang}/">{brand}</a><nav aria-label="{'Навигация' if ru else 'Navigation'}"><a href="/{lang}/">{'Главная' if ru else 'Home'}</a><a href="#about">{about}</a><a href="#services">{services}</a><button class="nav-contact">{contact}</button></nav><details class="mobile-menu"><summary aria-label="{'Открыть меню' if ru else 'Open menu'}"><span class="menu-bars" aria-hidden="true"></span><span aria-hidden="true">⌄</span></summary><div class="mobile-menu-links"><a href="/{lang}/">{'Главная' if ru else 'Home'}</a><a href="#about">{about}</a><a href="#services">{services}</a><button class="nav-contact">{contact}</button></div></details><a class="language" href="/{'en' if ru else 'ru'}/" aria-label="{'Перейти на английскую версию' if ru else 'Switch to Russian version'}">{'EN' if ru else 'RU'} <span aria-hidden="true">⌄</span></a></header><main><section class="hero" id="about"><img class="hero-photo" src="/hero-workspace-v3.png" alt="{'Светлый рабочий стол с ноутбуком и чашкой с зелёным глобусом' if ru else 'Sunlit desk with a laptop and a green globe mug'}"><p class="mobile-wall-caption">{strap}</p><div class="hero-inner wrap"><div class="hero-copy"><p class="eyebrow">{'20+ лет опыта' if ru else '20+ years of experience'}</p><h1>{headline}<span>{accent}</span></h1><p class="intro">{html.escape(intro)}</p><a class="hero-link" href="#services">{find} <span aria-hidden="true">→</span></a></div></div></section><section class="services wrap" id="services"><div class="section-heading"><p class="eyebrow">{strap}</p><h2><span class="desktop-question">{html.escape(question)}</span><span class="mobile-question">{html.escape(question) if ru else 'What Do You Need AI to Help You With?'}</span></h2></div><div class="cards">{''.join(cards)}</div></section></main><footer class="wrap"><span>{brand}</span><span>© 2026</span></footer><dialog aria-label="{'Подробнее об услуге' if ru else 'Service details'}"><button class="close" aria-label="{'Закрыть' if ru else 'Close'}">×</button><div id="dialog-content"></div></dialog>{''.join(templates)}<template id="contact-content"><h2>{'Обсудить мой проект' if ru else 'Discuss My Project'}</h2><p>{'Способ связи пока не подключён. Вы можете скопировать выбранное направление для дальнейшего обсуждения.' if ru else 'Contact is not connected yet. You can copy your selected service for a future discussion.'}</p><button class="copy-selection">{'Скопировать направление' if ru else 'Copy Selected Service'}</button></template><script src="/app.js?v=20261005-7"></script></body></html>'''
 (root/'dist'/lang/'index.html').write_text(page)
(root/'dist'/'index.html').write_text((root/'dist'/'ru'/'index.html').read_text())
